CREATE TABLE IF NOT EXISTS public.mentoring_lectures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.mentoring_courses(id) ON DELETE CASCADE, channel_id uuid REFERENCES public.mentoring_channels(id) ON DELETE SET NULL, title text NOT NULL, description text, recording_url text, duration_seconds integer, min_tier integer NOT NULL DEFAULT 1, recorded_at timestamptz NOT NULL DEFAULT now(), created_by uuid, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_mentoring_lectures_course ON public.mentoring_lectures(course_id); ALTER TABLE public.mentoring_lectures ENABLE ROW LEVEL SECURITY; CREATE POLICY "Hub members view lectures by tier" ON public.mentoring_lectures FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id) OR EXISTS (SELECT 1 FROM public.mentoring_hub_members m WHERE m.course_id = mentoring_lectures.course_id AND m.user_id = auth.uid() AND m.banned = false AND m.package_tier >= mentoring_lectures.min_tier)); CREATE POLICY "Mentors admins manage lectures" ON public.mentoring_lectures FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id)) WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id));